/*selectSellerMpIvBuyerCarInfoList*/
SELECT
	  NVL(CAR_FLAG,'N') AS CAR_FLAG 
FROM ICOMCMPY  
WHERE 
	COM_CODE = #{st_buyer}


/*selectOrderNo*/
SELECT 
	DOC_TYPE||SUBSTR(YEAR,3,2)||LPAD(CUR_NO,6,0) AS ORDER_NO
FROM ICOMSQMT
WHERE
		COMPANY		= #{st_seller} 
	AND DOC_TYPE	= #{doc_type}


/*selectCheckInvoice*/
SELECT COUNT(*) 
FROM ICOMPODT
WHERE 
		BUYER		= #{buyer}
	AND PO_NO		= #{po_no}
	AND PO_SEQ		= #{po_seq}
	AND STATUS 		^='D'			
	AND NVL(IV_QTY+${cd_qty} ,0) > ITEM_QTY


/*selectCompleteMarkDis*/
SELECT
	COMPLETE_MARK_DIS
FROM
	(	SELECT DECODE(COUNT(DISTINCT COMPLETE_MARK),1,MIN(COMPLETE_MARK),'NO') AS COMPLETE_MARK_DIS
		FROM   ICOMPODT
		WHERE
				BUYER = #{buyer}
			AND PO_NO = #{po_no}
			AND STATUS != 'D' 
	)
WHERE COMPLETE_MARK_DIS = 'Y'

