UPDATE ICOMPOHD
SET
	COMPLETE_MARK = 'Y'
WHERE
		BUYER = #{buyer}
	AND PO_NO = #{po_no}

/*insertSellerMpivTranStatementWriteIvhd*/ INSERT INTO ICOMIVHD ( SELLER , INV_NO , BUYER , STATUS , SEND_DATE , SEND_TIME , ADD_DATE , ADD_TIME , CHANGE_DATE , CHANGE_TIME , CONFIRM_DATE , CONFIRM_TIME , VENDOR_GI_DATE , VENDOR_GI_TIME , NOTIFY , PAYER , PAYEE , INV_TYPE , INV_DATE , CUR , INV_TTL_AMT , INV_AMT , INV_TAX_AMT_1 , INV_TAX_RATE_1 , INTEREST_AMT , COMMERCIAL_FLAG , PAY_TERMS , USANCE_DAYS , PAY_TEXT , DELY_TERMS , DANGER_GOOD_FLAG , PKG_TYPE , PKG_QTY , WEIGHT_UNIT , GROSS_WEIGHT , MEASUREMENT , SHIP_METHOD , SHIP_COUNTRY , DEPART_PORT , ARRIVAL_PORT , REMARK_INV , OUTGOING_FWDR_CODE , INCOMING_FWDR_CODE , VERSION , ADD_USER_ID , SHIPPER_TYPE , LC_NO , PURCHASER_ID , PURCHASER_DEPT , AGENT , LEGACY_IV_SERIAL , PARCEL_YN
, AGENCY_USER_ID
, CAR_NO , CAR_PERSON_NAME , CAR_PERSON_TEL
) ( SELECT SELLER , #{inv_no} -- 1 INV_NO , A.BUYER , 'C' , ' ' , ' ' , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , ' ' , ' ' , ' ' , ' ' , NOTIFY , PAYER , PAYEE , #{st_process_type} -- 2 PROCESS_TYPE , #{st_invoice_date_text} -- 3 INV_DATE , CUR --화면에서 계산해서 넘어온 값을 최종 DT테이블에서 읽어오기로 하여 원천 봉쇄 2014.12.17 김지현. , B.INV_AMT + FLOOR(B.INV_AMT/10) -- ${sheet_inv_tot_amt} -- 4 INV_TTL_AMT , B.INV_AMT -- ${sheet_inv_amt} -- 5 INV_AMT , FLOOR(B.INV_AMT/10) -- ${sheet_inv_tax_amt} -- 6 INV_TAX_AMT_1 --화면에서 계산해서 넘어온 값을 최종 DT테이블에서 읽어오기로 하여 원천 봉쇄 2014.12.17 김지현. , ${st_inv_tax_rate} -- 7 INV_TAX_RATE_1 , 0 , 'Y' , PAY_TERMS , USANCE_DAYS , ( SELECT CODE FROM ICOMCOD1 WHERE TYPE ='M010' AND CODE = PAY_TERMS) || ' ' || DECODE(NVL(USANCE_DAYS,'0'),0,'',USANCE_DAYS || 'DAYS ' ) || (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='M011' AND CODE = NVL(BLD_1,'')) , DELY_TERMS , #{danger_good_flag} -- 8 DANGER_GOOD_FLAG , #{pkg_type} -- 9 PKG_TYPE , #{pkg_qty} -- 10 PKG_QTY , #{weight_unit} -- 11 WEIGHT_UNIT , #{gross_weight} -- 12 GROSS_WEIGHT , #{measurement} -- 13 MEASUREMENT , #{ship_method} -- 14 SHIP_METHOD , SUBSTR(DEPART_PORT,1,2) , #{depart_port} -- 15 DEPART_PORT , #{arrival_port} -- 16 ARRIVAL_PORT , #{st_remark} -- 17 REMARK_INV , OUTGOING_FWDR_CODE , INCOMING_FWDR_CODE , '1' , #{st_user_id} -- 18 ADD_USER_ID , SHIPPER_TYPE , #{lc_no} -- 19 LC_NO, , PURCHASER_ID , CHANGE_USER_DEPT , AGENT , #{legacy_iv_serial} -- 20 LEGACY_IV_SERIAL , #{st_parcel_yn} -- 21 PARCEL_YN
, #{st_kep_id}
, #{car_no} , #{car_person_name} , #{car_person_tel}
FROM ICOMPOHD A , (SELECT SUM(ITEM_AMT) INV_AMT , MAX(BUYER) BUYER FROM ICOMIVDT WHERE BUYER = #{buyer} AND INV_NO = #{inv_no} AND STATUS != 'D' ) B WHERE 1=1 AND A.BUYER = B.BUYER(+) AND A.BUYER = #{buyer} -- 24 BUYER AND A.PO_NO = #{po_no} -- 25 PO_NO AND A.STATUS != 'D' )

