/*selectLegacyIvSerial*/
SELECT
	NVL(TO_CHAR(DECODE(TRIM(X.LEGACY_IV_SERIAL),NULL,Y.SERIAL,X.LEGACY_IV_SERIAL),'FM000'),'X')
FROM  
	  ICOMIVHD X
	, (	SELECT NVL(MAX(B.LEGACY_IV_SERIAL),0) + 1 AS SERIAL 
		FROM ICOMIVDT A, ICOMIVHD B
		WHERE 
				A.BUYER		= #{buyer}
			AND A.REF_PR_NO = #{st_legacy_po_no}
			AND A.BUYER     = B.BUYER
			AND A.INV_NO    = B.INV_NO
	) Y
WHERE
		X.BUYER   = #{buyer}
	AND X.STATUS ^= 'D'
	AND X.INV_NO  = #{inv_no}

/*selectSellerMpIvTranStatementWriteDiPopList*/ SELECT MAX(A.PO_CREATE_DATE) AS PO_CREATE_DATE -- 발주일[0] , MAX(B.PO_NO) AS PO_NO -- 발주번호[1] , C.DS_DATE -- 납품예정일[2] , SUM(B.AGENT_PRICE*(C.CD_QTY-NVL(D.INV_QTY,0))) AS CD_TTL_AMT -- 납품총금액[3] , MAX(( SELECT COUNT(*) FROM ICOMPORS WHERE BUYER = C.BUYER AND PO_NO = C.PO_NO AND DS_DATE= C.DS_DATE AND COMPLETE_MARK = 'N' AND STATUS <> 'D')) AS CD_ITEM_QTY -- 납품품목수[4] , MIN(B.RD_DATE) AS RD_DATE -- 납기요청일[5] , C.BUYER , MAX(A.PROCESS_TYPE) AS PROCESS_TYPE , MAX(DECODE(TRIM(LEGACY_PO_NO), NULL,'N',LEGACY_PO_NO)) AS LEGACY_PO_NO , MAX(DECODE(B.PROCESS_TYPE,'2',B.WAREHOUSE_CODE,B.BUYER)) AS TR_BUYER , MAX(A.AGENT) AS AGENT , MAX(B.PLANT) AS PLANT , COUNT(B.LEGACY_PO_SEQ) AS CNT_SEQ -- [12] FROM ICOMPOHD A, ICOMPODT B, ICOMPORS C, ICOMIVDT D WHERE A.AGENT = #{st_com_code} AND B.BUYER = #{st_buyer} AND B.PROCESS_TYPE = #{st_process_type} AND B.BUYER = A.BUYER AND B.PO_NO = A.PO_NO AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND B.PO_SEQ= C.PO_SEQ AND NVL(B.ITEM_QTY,0) > NVL(B.IV_QTY,0) AND C.BUYER = D.BUYER(+) AND C.PO_NO = D.PO_NO(+) AND C.PO_SEQ = D.PO_SEQ(+) AND C.DS_DATE= D.DS_DATE(+) AND B.DS_FLAG = 'Y' AND A.COMPLETE_MARK = 'N' AND B.COMPLETE_MARK = 'N' AND C.COMPLETE_MARK = 'N' AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND D.STATUS(+) <> 'D'
AND B.ITEM_QTY ^= B.GR_QTY
GROUP BY C.BUYER, C.PO_NO, C.DS_DATE ORDER BY C.BUYER, C.DS_DATE

/*getSellerMpIvTranStatementWriteDiPop_v2*/ SELECT MAX(A.PO_CREATE_DATE) AS PO_CREATE_DATE -- 발주일[0] , MAX(B.PO_NO) AS PO_NO -- 발주번호[1] , C.DS_DATE -- 납품예정일[2] , SUM(B.AGENT_PRICE*(C.CD_QTY-NVL(D.INV_QTY,0))) AS CD_TTL_AMT -- 납품총금액[3] , MAX(( SELECT COUNT(*) FROM ICOMPORS WHERE BUYER = C.BUYER AND PO_NO = C.PO_NO AND DS_DATE= C.DS_DATE AND COMPLETE_MARK = 'N' AND STATUS <> 'D')) AS CD_ITEM_QTY -- 납품품목수[4] , MIN(B.RD_DATE) AS RD_DATE -- 납기요청일[5] , C.BUYER , MAX(A.PROCESS_TYPE) AS PROCESS_TYPE , MAX(DECODE(TRIM(LEGACY_PO_NO), NULL,'N',LEGACY_PO_NO)) AS LEGACY_PO_NO , MAX(DECODE(B.PROCESS_TYPE,'2',B.WAREHOUSE_CODE,B.BUYER)) AS TR_BUYER , MAX(A.AGENT) AS AGENT , MAX(B.PLANT) AS PLANT , COUNT(B.LEGACY_PO_SEQ) AS CNT_SEQ -- [12] FROM ICOMPOHD A, ICOMPODT B, ICOMPORS C, ICOMIVDT D WHERE A.AGENT = #{st_com_code} AND B.BUYER = #{st_buyer} AND B.PROCESS_TYPE = #{st_process_type} AND B.BUYER = A.BUYER AND B.PO_NO = A.PO_NO AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND B.PO_SEQ= C.PO_SEQ AND NVL(B.ITEM_QTY,0) > NVL(B.IV_QTY,0) AND C.BUYER = D.BUYER(+) AND C.PO_NO = D.PO_NO(+) AND C.PO_SEQ = D.PO_SEQ(+) AND C.DS_DATE= D.DS_DATE(+) AND B.DS_FLAG = 'Y' AND A.COMPLETE_MARK = 'N' AND B.COMPLETE_MARK = 'N' AND C.COMPLETE_MARK = 'N' AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND D.STATUS(+) <> 'D'
AND B.ITEM_QTY ^= B.GR_QTY
GROUP BY C.BUYER, C.PO_NO, C.DS_DATE ORDER BY C.BUYER, C.DS_DATE

/*selectSellerMpIvTranStatementWritePoList*/ SELECT DISTINCT B.LEGACY_PO_NO||B.LEGACY_PO_SEQ AS LEGACY_PO FROM ICOMPOHD A, ICOMPODT B, ICOMPORS C, ICOMIVDT D WHERE A.AGENT = #{st_agent} AND B.BUYER = #{st_buyer} AND B.PO_NO IN ( ${st_query} ) AND B.PROCESS_TYPE = '0' AND B.BUYER = A.BUYER AND B.PO_NO = A.PO_NO AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND B.PO_SEQ= C.PO_SEQ AND NVL(B.ITEM_QTY,0) > NVL(B.IV_QTY,0) AND C.BUYER = D.BUYER(+) AND C.PO_NO = D.PO_NO(+) AND C.PO_SEQ = D.PO_SEQ(+) AND C.DS_DATE= D.DS_DATE(+) AND B.DS_FLAG = 'Y' AND A.COMPLETE_MARK = 'N' AND B.COMPLETE_MARK = 'N' AND C.COMPLETE_MARK = 'N' AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND D.STATUS(+) <> 'D'
AND B.ITEM_QTY ^= B.GR_QTY
ORDER BY LEGACY_PO

