UPDATE ICOMIVHD SET
	  SEND_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
	, SEND_TIME = TO_CHAR(SYSDATE, 'HH24MISS')
WHERE 
		BUYER = #{st_buyer}
	AND INV_NO = #{st_inv_no}

mapper.select:
/*getSellerMpIvTranStatementWriteListItemAll_v2*/ SELECT XX.BUYER, XX.PO_NO, XX.AGENT_PRICE * (XX.SUM_CD_QTY-NVL(XX.SUM_INV_QTY,0)) AS AGENT_TOT_AMT, XX.AGENT_PRICE * (XX.SUM_CD_QTY-NVL(XX.SUM_INV_QTY,0)) AS SELLER_AMT, FLOOR(XX.AGENT_PRICE * (XX.SUM_CD_QTY-NVL(XX.SUM_INV_QTY,0))/10) AS TAX_AMT, XX.LEGACY_PO_NO, XX.PURCHASER_ID, XX.TR_BUYER, XX.AGENT_PRICE, XX.PROCESS_TYPE, XX.QRY_STR1, XX.QRY_STR2, XX.QRY_STR3, XX.QRY_STR4 FROM ( SELECT SUM(C.CD_QTY) OVER(PARTITION BY C.BUYER, C.PO_NO, C.DS_DATE) AS SUM_CD_QTY , (SELECT SUM(INV_QTY) AS INV_QTY FROM ICOMIVDT IVDT WHERE IVDT.BUYER = B.BUYER AND IVDT.PO_NO = B.PO_NO AND IVDT.PO_SEQ = B.PO_SEQ AND IVDT.DS_DATE = C.DS_DATE AND IVDT.STATUS <> 'D') SUM_INV_QTY , B.AGENT_PRICE , A.PROCESS_TYPE , Z.QRY_STR1 , Z.QRY_STR2 , Z.QRY_STR3 , Z.QRY_STR4 , DECODE(TRIM(B.LEGACY_PO_NO), NULL,'N',B.LEGACY_PO_NO) AS LEGACY_PO_NO , A.PURCHASER_ID , DECODE(B.PROCESS_TYPE,'2',B.WAREHOUSE_CODE,B.BUYER) AS TR_BUYER , A.BUYER , B.PO_NO FROM ICOMPOHD A, ICOMPODT B, ICOMPORS C, ICOMPRDT P, ( SELECT Y.QRY_STR1 , Y.QRY_STR2 , Y.QRY_STR3 , Y.QRY_STR4 , X.SLG_ID , X.DEFAULT_RPT_URL FROM /* SLOGIC-BEGIN (P06-0000002) */ (
SELECT 'P06-0000002' SLG_ID -- ID 하드코딩 , 'RD_06_S_001_83' DEFAULT_RPT_URL --디폴트 유알엘 하드코딩 , 추후 변경 /kr/epro/buy/sheet/inv_prn.jsp FROM DUAL --한건도 조회되지 않는 것 방지
) X , ( SELECT B.COL01_DATA QRY_STR1 , B.COL02_DATA QRY_STR2 , B.COL03_DATA QRY_STR3 , B.COL03_DATA QRY_STR4 , A.SLG_ID FROM BNTSLGDEF A, BNTSLGIMP B WHERE 1=1 AND A.SLG_ID = B.SLG_ID --default url을 가져오기 위해 아우터조인 AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.OPEN_DATE AND A.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.OPEN_DATE AND B.CLOSE_DATE AND B.COM_CODE = #{st_buyer_code} --고객사 회사코드 AND A.SLG_ID = 'P06-0000002' -- ID하드코딩 ) Y /* SLOGIC-END */ WHERE 1=1 AND X.SLG_ID = Y.SLG_ID(+) ) Z WHERE 1=1 AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND B.PO_SEQ= C.PO_SEQ AND B.BUYER = P.BUYER AND B.PR_NO = P.PR_NO AND B.PR_SEQ = P.PR_SEQ AND A.AGENT = #{st_com_code} --param: session com_code AND C.AGENT = #{st_com_code} AND A.COMPLETE_MARK = 'N' AND A.STATUS <> 'D' AND B.DS_FLAG = 'Y' AND B.COMPLETE_MARK = 'N' AND B.STATUS <> 'D' AND C.COMPLETE_MARK = 'N' AND C.STATUS <> 'D' AND P.STATUS <> 'D' AND NVL(B.CLSD_FLAG,'N') <> 'Y' AND A.BUYER = #{st_buyer_code} AND C.PO_NO = #{st_po_no_all} AND NOT EXISTS (SELECT 'X' FROM KEP_PO_MNG WHERE STATUS = 'S' AND TYPE IN ('D','E','G','I') AND BUYER= A.BUYER AND PO_NO = A.PO_NO ) AND NOT EXISTS (SELECT 'X' FROM ICOMTRXL WHERE DOC_NAME = 'MHUB_CHG' AND TARGET = A.BUYER AND KEY_1 = A.PO_NO AND KEY_9 = 'N') AND B.ITEM_QTY != B.GR_QTY ) XX
